{
	"name": "@oh-my-opencode/pi-goal",
	"version": "4.15.1",
	"type": "module",
	"private": true,
	"description": "Persistent goal tracking Pi extension with Codex-style goal tools, TUI footer, and continuation prompts. Vendored from code-yeongyu/pi-goal.",
	"license": "MIT",
	"pi": {
		"extensions": [
			"./src/index.ts"
		]
	},
	"scripts": {
		"typecheck": "tsgo --noEmit -p tsconfig.json",
		"test": "bun test test"
	},
	"peerDependencies": {
		"@mariozechner/pi-ai": "*",
		"@mariozechner/pi-coding-agent": "*",
		"@mariozechner/pi-tui": "*",
		"typebox": "*"
	},
	"peerDependenciesMeta": {
		"@mariozechner/pi-ai": {
			"optional": true
		},
		"@mariozechner/pi-coding-agent": {
			"optional": true
		},
		"@mariozechner/pi-tui": {
			"optional": true
		},
		"typebox": {
			"optional": true
		}
	},
	"devDependencies": {
		"@mariozechner/pi-coding-agent": "0.73.1",
		"@mariozechner/pi-tui": "0.73.1",
		"typebox": "1.3.16"
	}
}

#!/usr/bin/env node
// Live QA driver: boots the REAL pi coding agent CLI in RPC mode inside an
// isolated PI_CODING_AGENT_DIR sandbox, loads the vendored pi-goal extension
// plus a scripted mock provider (no network), and proves the goal tools and
// continuation wiring work end to end on the real harness. Two scenarios:
//   complete: turn 1 creates the goal, the extension queues a hidden
//             continuation prompt, and the continuation turn marks it complete.
//   blocked:  turn 1 creates the goal, and the continuation turn marks it
//             blocked via update_goal (codex-aligned status).
// Runs both by default; pass --scenario <complete|blocked> to run one.
import { spawn } from "node:child_process"
import { createHash } from "node:crypto"
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs"
import { homedir, tmpdir } from "node:os"
import { dirname, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const scriptDir = dirname(fileURLToPath(import.meta.url))
const packageRoot = resolve(scriptDir, "..", "..")
const mockProviderEntry = join(scriptDir, "mock-provider", "index.ts")
const goalExtensionEntry = join(packageRoot, "src", "index.ts")
const realPiAgentDir = join(homedir(), ".pi", "agent")
const RUN_TIMEOUT_MILLISECONDS = 120_000
const CONTINUATION_MARKER = "Continue working toward the active thread goal."
// Present only in the codex-aligned continuation prompt, so its delivery proves
// the new prompt content actually reached the real session (not the old prompt).
const CODEX_CONTINUATION_MARKER = "Blocked audit:"

const SCENARIOS = {
  complete: {
    objective: "QA: prove pi-goal works on the real pi harness",
    tokenBudget: 50_000,
    steps: [
      {
        type: "tool_call",
        name: "create_goal",
        arguments: { objective: "QA: prove pi-goal works on the real pi harness", token_budget: 50_000 },
      },
      { type: "text", text: "goal created, ending this turn" },
      { type: "tool_call", name: "update_goal", arguments: { status: "complete" } },
      { type: "text", text: "goal completed, all done" },
    ],
    terminalStatus: "complete",
  },
  blocked: {
    objective: "QA: prove the blocked round-trip on the real pi harness",
    tokenBudget: undefined,
    steps: [
      {
        type: "tool_call",
        name: "create_goal",
        arguments: { objective: "QA: prove the blocked round-trip on the real pi harness" },
      },
      { type: "text", text: "goal created, ending this turn" },
      { type: "tool_call", name: "update_goal", arguments: { status: "blocked" } },
      { type: "text", text: "goal blocked, stopping" },
    ],
    terminalStatus: "blocked",
  },
}

export function createSandbox() {
  const root = mkdtempSync(join(tmpdir(), "pi-goal-qa-"))
  const cwd = join(root, "project")
  const agentDir = join(root, "agent")
  mkdirSync(cwd, { recursive: true })
  mkdirSync(agentDir, { recursive: true })
  return { root, cwd, agentDir }
}

export function digestDirectory(root) {
  if (!existsSync(root)) return "absent"
  const files = []
  collectFiles(root, files)
  const hash = createHash("sha256")
  for (const file of files.sort()) {
    hash.update(file.slice(root.length + 1))
    hash.update("\0")
    hash.update(createHash("sha256").update(readFileSync(file)).digest("hex"))
    hash.update("\0")
  }
  return hash.digest("hex")
}

function collectFiles(root, out) {
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    const path = join(root, entry.name)
    if (entry.isDirectory()) collectFiles(path, out)
    else if (entry.isFile()) out.push(path)
  }
}

export function readSandboxText(root) {
  const files = []
  collectFiles(root, files)
  let text = ""
  for (const file of files.sort()) {
    try {
      text += readFileSync(file, "utf8")
    } catch {
      // @allow binary or unreadable files are irrelevant to the assertions
    }
  }
  return text
}

export function findGoalStoreFiles(root) {
  const files = []
  collectFiles(root, files)
  return files.filter((file) => file.includes(join("extensions", "pi-goal")) && file.endsWith(".json"))
}

export function resolvePiBin() {
  let dir = packageRoot
  while (true) {
    const candidate = join(dir, "node_modules", "@mariozechner", "pi-coding-agent")
    if (existsSync(join(candidate, "package.json"))) {
      const manifest = JSON.parse(readFileSync(join(candidate, "package.json"), "utf8"))
      return join(candidate, manifest.bin.pi)
    }
    const parent = dirname(dir)
    if (parent === dir) return null
    dir = parent
  }
}

function readGoalFromSandbox(root) {
  const goalFiles = findGoalStoreFiles(root)
  if (goalFiles.length === 0) return { file: undefined, goal: undefined }
  return { file: goalFiles[0], goal: JSON.parse(readFileSync(goalFiles[0], "utf8")).goal }
}

function runRpcScenario(piBin, sandbox, scenario, scenarioReport) {
  writeFileSync(join(sandbox.cwd, "mock-script.json"), `${JSON.stringify({ steps: scenario.steps }, null, 2)}\n`)

  const child = spawn(
    process.execPath,
    [piBin, "--mode", "rpc", "--offline", "-e", mockProviderEntry, "-e", goalExtensionEntry, "--provider", "omo-mock", "--model", "mock-1"],
    {
      cwd: sandbox.cwd,
      env: { ...process.env, PI_CODING_AGENT_DIR: sandbox.agentDir },
      stdio: ["pipe", "pipe", "pipe"],
    },
  )
  scenarioReport.childPid = child.pid

  return new Promise((resolveScenario) => {
    let stdoutBuffer = ""
    let stderrTail = ""
    let agentEndCount = 0
    let settled = false
    const timeout = setTimeout(() => finish("timeout"), RUN_TIMEOUT_MILLISECONDS)

    function finish(reason) {
      if (settled) return
      settled = true
      clearTimeout(timeout)
      scenarioReport.rpcFinishReason = reason
      scenarioReport.agentEndCount = agentEndCount
      scenarioReport.stderrTail = stderrTail.split("\n").slice(-8).join("\n")
      child.kill("SIGTERM")
      const killTimeout = setTimeout(() => child.kill("SIGKILL"), 5_000)
      child.once("exit", () => {
        clearTimeout(killTimeout)
        resolveScenario()
      })
      if (child.exitCode !== null) {
        clearTimeout(killTimeout)
        resolveScenario()
      }
    }

    child.on("error", () => finish("spawn-error"))
    child.on("exit", () => finish("child-exited"))
    child.stderr.on("data", (chunk) => {
      stderrTail = `${stderrTail}${chunk}`.slice(-4_000)
    })
    child.stdout.on("data", (chunk) => {
      stdoutBuffer += chunk
      let newlineIndex = stdoutBuffer.indexOf("\n")
      while (newlineIndex !== -1) {
        const line = stdoutBuffer.slice(0, newlineIndex)
        stdoutBuffer = stdoutBuffer.slice(newlineIndex + 1)
        handleLine(line)
        newlineIndex = stdoutBuffer.indexOf("\n")
      }
    })

    function handleLine(line) {
      if (line.trim() === "") return
      let event
      try {
        event = JSON.parse(line)
      } catch {
        return
      }
      if (event.type === "agent_end") {
        agentEndCount += 1
        const { goal } = readGoalFromSandbox(sandbox.root)
        if (goal?.status === scenario.terminalStatus) finish(`goal-${scenario.terminalStatus}`)
        else if (agentEndCount >= 4) finish("terminal-status-never-reached")
      }
    }

    child.stdin.write(`${JSON.stringify({ type: "prompt", message: "please create the QA goal" })}\n`)
  })
}

async function runScenario(piBin, name) {
  const scenario = SCENARIOS[name]
  const sandbox = createSandbox()
  const scenarioReport = {
    scenario: name,
    result: "FAIL",
    reason: undefined,
    goalStoreFile: undefined,
    goalAfterRun: undefined,
    continuationObserved: false,
    codexContinuationMarkerObserved: false,
    terminalStatusObserved: false,
    sandboxRoot: sandbox.root,
  }
  try {
    await runRpcScenario(piBin, sandbox, scenario, scenarioReport)
    const { file, goal } = readGoalFromSandbox(sandbox.root)
    scenarioReport.goalStoreFile = file
    scenarioReport.goalAfterRun = goal
    const sandboxText = readSandboxText(sandbox.root)
    scenarioReport.continuationObserved = sandboxText.includes(CONTINUATION_MARKER)
    scenarioReport.codexContinuationMarkerObserved = sandboxText.includes(CODEX_CONTINUATION_MARKER)
    scenarioReport.terminalStatusObserved = goal?.status === scenario.terminalStatus

    const shapeCorrect = goal?.objective === scenario.objective && goal?.tokenBudget === scenario.tokenBudget
    if (
      shapeCorrect &&
      scenarioReport.continuationObserved &&
      scenarioReport.codexContinuationMarkerObserved &&
      scenarioReport.terminalStatusObserved
    ) {
      scenarioReport.result = "PASS"
    } else {
      scenarioReport.reason = "assertions-not-satisfied"
    }
  } finally {
    if (scenarioReport.result === "PASS") rmSync(sandbox.root, { recursive: true, force: true })
  }
  return scenarioReport
}

function runSelfTest() {
  const sandbox = createSandbox()
  try {
    if (!existsSync(mockProviderEntry)) throw new Error("mock provider entry missing")
    if (!existsSync(goalExtensionEntry)) throw new Error("goal extension entry missing")
    if (sandbox.agentDir === realPiAgentDir) throw new Error("sandbox reused the real pi agent dir")
    if (digestDirectory(join(sandbox.root, "missing")) !== "absent") throw new Error("missing dir digest should be absent")
    writeFileSync(join(sandbox.cwd, "probe.json"), "{}")
    if (findGoalStoreFiles(sandbox.root).length !== 0) throw new Error("goal store matcher over-matches")
    if (resolvePiBin() === null) throw new Error("pi binary could not be resolved from the workspace")
    if (SCENARIOS.blocked.terminalStatus !== "blocked") throw new Error("blocked scenario misconfigured")
    console.log(JSON.stringify({ result: "PASS", mode: "self-test" }))
  } finally {
    rmSync(sandbox.root, { recursive: true, force: true })
  }
}

function selectedScenarioNames() {
  const flagIndex = process.argv.indexOf("--scenario")
  if (flagIndex !== -1 && process.argv[flagIndex + 1]) {
    const name = process.argv[flagIndex + 1]
    if (!SCENARIOS[name]) throw new Error(`unknown scenario: ${name}`)
    return [name]
  }
  return Object.keys(SCENARIOS)
}

async function main() {
  if (process.argv.includes("--self-test")) return runSelfTest()

  const beforeDigest = digestDirectory(realPiAgentDir)
  const report = {
    result: "FAIL",
    piBin: undefined,
    realAgentDirUntouched: undefined,
    scenarios: [],
  }

  try {
    const piBin = resolvePiBin()
    if (piBin === null || !existsSync(piBin)) {
      report.result = "SKIP"
      report.reason = "pi-binary-unavailable"
      return
    }
    report.piBin = piBin

    for (const name of selectedScenarioNames()) {
      report.scenarios.push(await runScenario(piBin, name))
    }
    report.result = report.scenarios.every((scenarioReport) => scenarioReport.result === "PASS") ? "PASS" : "FAIL"
  } finally {
    report.realAgentDirUntouched = digestDirectory(realPiAgentDir) === beforeDigest
    if (report.result === "PASS" && !report.realAgentDirUntouched) {
      report.result = "FAIL"
      report.reason = "real-pi-agent-dir-mutated"
    }
    console.log(JSON.stringify(report, null, 2))
    process.exitCode = report.result === "PASS" || report.result === "SKIP" ? 0 : 1
  }
}

await main()

#!/usr/bin/env node
// allow: SIZE_OK - one-process manual QA mock provider keeps SSE, health, and chat endpoints in one launched fixture.
declare const process: {
  argv: string[]
  cwd(): string
  getBuiltinModule<T>(id: string): T
}

interface FsModule {
  existsSync(path: string): boolean
  readFileSync(path: string, encoding: string): string
  rmSync(path: string, options?: { force?: boolean; recursive?: boolean }): void
  writeFileSync(path: string, data: string): void
}

interface PathModule {
  dirname(path: string): string
  join(...paths: string[]): string
}

interface UrlModule {
  fileURLToPath(url: string | { href: string }): string
  pathToFileURL(path: string): { href: string }
}

const { existsSync, readFileSync, rmSync, writeFileSync } = process.getBuiltinModule<FsModule>("fs")
const { dirname, join } = process.getBuiltinModule<PathModule>("path")
const { fileURLToPath, pathToFileURL } = process.getBuiltinModule<UrlModule>("url")

type MockStep =
  | { type: "text"; text: string }
  | { type: "tool_call"; name: string; arguments: Record<string, unknown>; id?: string }

interface MockScript {
  steps: MockStep[]
}

type LocalStreamEvent = unknown

type Api = "openai-completions"
type StopReason = "stop" | "toolUse" | "aborted"

interface Model<TApi extends string = Api> {
  id: string
  api?: TApi
}

interface Context {
  cwd?: string
  messages?: Array<{ role?: string }>
}

interface SimpleStreamOptions {
  signal?: AbortSignal
}

type AssistantContent =
  | { type: "text"; text: string }
  | { type: "toolCall"; id: string; name: string; arguments: Record<string, unknown> }

interface AssistantMessage {
  role: "assistant"
  content: AssistantContent[]
  api: Api
  provider: "omo-mock"
  model: "mock-1"
  usage: { input: number; output: number; cacheRead: number; cacheWrite: number; totalTokens: number; cost: number }
  stopReason: StopReason
  timestamp: number
}

interface MockProvider {
  name: string
  baseUrl: string
  apiKey: string
  api: Api
  models: Array<{
    id: string
    name: string
    reasoning: boolean
    input: Array<"text" | "image">
    cost: { input: number; output: number; cacheRead: number; cacheWrite: number }
    contextWindow: number
    maxTokens: number
  }>
  streamSimple(model: Model<Api>, context: Context, options?: SimpleStreamOptions): AsyncIterable<LocalStreamEvent> & {
    result(): Promise<AssistantMessage>
  }
}

interface ExtensionAPI {
  registerProvider(id: string, provider: MockProvider): void
}

interface LocalAssistantMessageEventStream extends AsyncIterable<LocalStreamEvent> {
  push(event: LocalStreamEvent): void
  end(message: AssistantMessage): void
  fail(error: unknown): void
  result(): Promise<AssistantMessage>
}

const model = {
  id: "mock-1",
  name: "Mock 1",
  reasoning: false,
  input: ["text" as const],
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
  contextWindow: 16_000,
  maxTokens: 4096,
}

export default function registerMockProvider(pi: ExtensionAPI): void {
  pi.registerProvider("omo-mock", {
    name: "omo mock provider",
    baseUrl: "file://mock-provider",
    apiKey: "mock",
    api: "openai-completions",
    models: [model],
    streamSimple(streamModel: Model<Api>, context: Context, options?: SimpleStreamOptions) {
      return streamMockResponse(streamModel, context, options)
    },
  })
}

export function loadMockScript(cwd: string): MockScript {
  const scriptPath = join(cwd, "mock-script.json")
  if (!existsSync(scriptPath)) {
    return { steps: [{ type: "text", text: "omo mock provider default response" }] }
  }

  const parsed = JSON.parse(readFileSync(scriptPath, "utf8")) as unknown
  if (!isMockScript(parsed)) {
    throw new Error(`${scriptPath} must contain {"steps":[...]} with text or tool_call steps`)
  }
  return parsed
}

export function stepToAssistantMessage(step: MockStep, callCount: number): AssistantMessage {
  const content =
    step.type === "text"
      ? [{ type: "text" as const, text: step.text }]
      : [
          {
            type: "toolCall" as const,
            id: step.id ?? `omo-mock-tool-${callCount}`,
            name: step.name,
            arguments: step.arguments,
          },
        ]

  return {
    role: "assistant",
    content,
    api: "openai-completions",
    provider: "omo-mock",
    model: "mock-1",
    usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: 0 },
    stopReason: step.type === "tool_call" ? "toolUse" : "stop",
    timestamp: Date.now(),
  }
}

let callCount = 0

function streamMockResponse(_model: Model<Api>, context: Context, options?: SimpleStreamOptions) {
  const stream = createLocalAssistantMessageEventStream()
  const script = loadMockScript(context.cwd ?? process.cwd())
  // Select the step from the conversation shape instead of a global call
  // counter so out-of-band model calls (session title generation, summaries)
  // cannot consume scripted steps meant for the agent turns.
  const assistantMessageCount = (context.messages ?? []).filter((message) => message.role === "assistant").length
  const step = script.steps[Math.min(assistantMessageCount, script.steps.length - 1)]
  callCount += 1
  const message = stepToAssistantMessage(step, callCount)

  queueMicrotask(() => {
    if (options?.signal?.aborted) {
      const aborted = { ...message, stopReason: "aborted" as const }
      stream.push({ type: "error", reason: "aborted", error: aborted })
      stream.end(aborted)
      return
    }

    stream.push({ type: "start", partial: { ...message, content: [] } })
    if (step.type === "text") {
      const partial = { ...message, content: [{ type: "text" as const, text: "" }] }
      stream.push({ type: "text_start", contentIndex: 0, partial })
      stream.push({ type: "text_delta", contentIndex: 0, delta: step.text, partial: message })
      stream.push({ type: "text_end", contentIndex: 0, content: step.text, partial: message })
    } else {
      const toolCall = message.content[0]
      stream.push({ type: "toolcall_start", contentIndex: 0, partial: { ...message, content: [] } })
      stream.push({ type: "toolcall_delta", contentIndex: 0, delta: JSON.stringify(step.arguments), partial: message })
      stream.push({ type: "toolcall_end", contentIndex: 0, toolCall, partial: message })
    }
    stream.push({ type: "done", reason: message.stopReason, message })
    stream.end(message)
  })

  return stream
}

export function createLocalAssistantMessageEventStream(): LocalAssistantMessageEventStream {
  const queue: LocalStreamEvent[] = []
  const waiters: Array<(value: IteratorResult<LocalStreamEvent>) => void> = []
  let done = false
  let settleResult: (message: AssistantMessage) => void = () => {}
  let rejectResult: (error: unknown) => void = () => {}
  const finalMessage = new Promise<AssistantMessage>((resolve, reject) => {
    settleResult = resolve
    rejectResult = reject
  })
  finalMessage.catch(() => {})

  return {
    push(event: LocalStreamEvent) {
      if (done) return
      if (isTerminalAssistantMessageEvent(event)) {
        done = true
        settleResult(extractAssistantMessageResult(event))
      }
      const waiter = waiters.shift()
      if (waiter) waiter({ value: event, done: false })
      else queue.push(event)
    },
    end(message: AssistantMessage) {
      if (done) return
      done = true
      settleResult(message)
      while (waiters.length > 0) {
        const waiter = waiters.shift()
        if (waiter) waiter({ value: undefined, done: true })
      }
    },
    fail(error: unknown) {
      if (done) return
      done = true
      rejectResult(error)
      while (waiters.length > 0) {
        const waiter = waiters.shift()
        if (waiter) waiter({ value: undefined, done: true })
      }
    },
    result() {
      return finalMessage
    },
    [Symbol.asyncIterator]() {
      return {
        next() {
          if (queue.length > 0) return Promise.resolve({ value: queue.shift(), done: false })
          if (done) return Promise.resolve({ value: undefined, done: true })
          return new Promise<IteratorResult<LocalStreamEvent>>((resolve) => waiters.push(resolve))
        },
      }
    },
  }
}

function isTerminalAssistantMessageEvent(
  event: LocalStreamEvent,
): event is { type: "done"; message: AssistantMessage } | { type: "error"; error: AssistantMessage } {
  if (typeof event !== "object" || event === null) return false
  const candidate = event as { type?: unknown; message?: unknown; error?: unknown }
  if (candidate.type === "done") return isAssistantMessage(candidate.message)
  if (candidate.type === "error") return isAssistantMessage(candidate.error)
  return false
}

function extractAssistantMessageResult(event: { type: "done"; message: AssistantMessage } | { type: "error"; error: AssistantMessage }) {
  return event.type === "done" ? event.message : event.error
}

function isAssistantMessage(value: unknown): value is AssistantMessage {
  if (typeof value !== "object" || value === null) return false
  const candidate = value as { role?: unknown; content?: unknown; stopReason?: unknown }
  return candidate.role === "assistant" && Array.isArray(candidate.content) && typeof candidate.stopReason === "string"
}

function isMockScript(value: unknown): value is MockScript {
  if (typeof value !== "object" || value === null || !Array.isArray((value as { steps?: unknown }).steps)) return false
  return (value as { steps: unknown[] }).steps.every(isMockStep)
}

function isMockStep(value: unknown): value is MockStep {
  if (typeof value !== "object" || value === null) return false
  const candidate = value as Record<string, unknown>
  if (candidate.type === "text") return typeof candidate.text === "string"
  if (candidate.type !== "tool_call") return false
  return typeof candidate.name === "string" && typeof candidate.arguments === "object" && candidate.arguments !== null
}

export async function selfTest(): Promise<void> {
  const tmp = dirname(fileURLToPath(import.meta.url))
  const scriptPath = join(tmp, "mock-script.json")
  const previous = existsSync(scriptPath) ? readFileSync(scriptPath, "utf8") : undefined
  let capturedProvider: MockProvider | undefined
  try {
    writeFileSync(
      scriptPath,
      JSON.stringify({
        steps: [
          { type: "text", text: "hello" },
          { type: "tool_call", name: "write", arguments: { path: "x.ts", content: "const x = 1\n" } },
        ],
      }),
    )
    const script = loadMockScript(tmp)
    if (script.steps.length !== 2) throw new Error("expected two mock steps")
    if (stepToAssistantMessage(script.steps[0], 1).content[0]?.type !== "text") throw new Error("text step failed")
    const toolMessage = stepToAssistantMessage(script.steps[1], 2)
    if (toolMessage.content[0]?.type !== "toolCall") throw new Error("tool step failed")
    if (toolMessage.stopReason !== "toolUse") throw new Error("tool step must stop with toolUse")

    registerMockProvider({
      registerProvider(_id: string, provider: MockProvider) {
        capturedProvider = provider
      },
    })
    if (capturedProvider === undefined) throw new Error("mock provider was not registered")

    capturedProvider.streamSimple(model, { cwd: tmp })
    const stream = capturedProvider.streamSimple(model, { cwd: tmp })
    const events: LocalStreamEvent[] = []
    for await (const event of stream) events.push(event)
    const result = await stream.result()
    if (result.stopReason !== "toolUse") throw new Error("stream result must stop with toolUse")
    if (result.content[0]?.type !== "toolCall") throw new Error("stream result must contain toolCall content")
    if (!events.some((event) => isDoneToolUseEvent(event))) throw new Error("stream must emit done/toolUse")
  } finally {
    if (previous === undefined) {
      rmSync(scriptPath, { force: true })
    } else {
      writeFileSync(scriptPath, previous)
    }
  }
}

function isDoneToolUseEvent(event: LocalStreamEvent): boolean {
  if (typeof event !== "object" || event === null) return false
  const candidate = event as { type?: unknown; reason?: unknown }
  return candidate.type === "done" && candidate.reason === "toolUse"
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  if (process.argv.includes("--self-test")) {
    await selfTest()
    console.log("SELF-TEST OK")
  }
}

import type { GoalStatus } from "./types.js";

export type ParsedGoalCommand =
	| { kind: "show" }
	| { kind: "clear" }
	| { kind: "setStatus"; status: Extract<GoalStatus, "active" | "paused"> }
	| { kind: "setObjective"; objective: string };

export function parseGoalCommand(rawArgs: string): ParsedGoalCommand {
	const trimmed = rawArgs.trim();
	if (trimmed === "") return { kind: "show" };

	switch (trimmed.toLowerCase()) {
		case "pause":
			return { kind: "setStatus", status: "paused" };
		case "resume":
			return { kind: "setStatus", status: "active" };
		case "clear":
			return { kind: "clear" };
		default:
			return { kind: "setObjective", objective: trimmed };
	}
}

import type { Goal } from "./types.js";
import { isRecord } from "./types.js";

export function shouldQueueGoalContinuationWhenIdle(
	goal: Goal | null,
	isIdle: boolean,
	hasPendingMessages: boolean,
): goal is Goal {
	return goal?.status === "active" && isIdle && !hasPendingMessages;
}

export function shouldQueueGoalContinuationAfterAgentEnd(
	goal: Goal | null,
	hasPendingMessages: boolean,
	messages: readonly unknown[],
): goal is Goal {
	return goal?.status === "active" && !hasPendingMessages && didAgentEndCleanly(messages);
}

function didAgentEndCleanly(messages: readonly unknown[]): boolean {
	const lastAssistantIndex = findLastAssistantMessageIndex(messages);
	if (lastAssistantIndex === undefined) return false;

	const lastAssistant = messages[lastAssistantIndex];
	if (!isAssistantMessage(lastAssistant) || !isContinuableStopReason(lastAssistant["stopReason"])) return false;

	for (let index = lastAssistantIndex + 1; index < messages.length; index++) {
		const message = messages[index];
		if (isAbortedToolResult(message)) return false;
	}
	return true;
}

function findLastAssistantMessageIndex(messages: readonly unknown[]): number | undefined {
	for (let index = messages.length - 1; index >= 0; index--) {
		if (isAssistantMessage(messages[index])) return index;
	}
	return undefined;
}

function isAssistantMessage(message: unknown): message is Record<string, unknown> {
	return isRecord(message) && message["role"] === "assistant";
}

function isContinuableStopReason(stopReason: unknown): boolean {
	return stopReason === "stop" || stopReason === "toolUse" || stopReason === "length";
}

function isAbortedToolResult(message: unknown): boolean {
	if (!isRecord(message) || message["role"] !== "toolResult" || message["isError"] !== true) return false;
	const content = message["content"];
	if (!Array.isArray(content)) return false;
	return content.some(
		(block) =>
			isRecord(block) &&
			block["type"] === "text" &&
			typeof block["text"] === "string" &&
			/\babort(?:ed)?\b/i.test(block["text"]),
	);
}

export class GoalAlreadyExistsError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "GoalAlreadyExistsError";
	}
}

export class GoalNotFoundError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "GoalNotFoundError";
	}
}

export class InvalidGoalStoreError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "InvalidGoalStoreError";
	}
}

export class UnsupportedGoalStoreVersionError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "UnsupportedGoalStoreVersionError";
	}
}

import type { Goal, GoalStatus, GoalToolResponse, GoalToolSnapshot } from "./types.js";

export function formatGoalElapsedSeconds(value: number): string {
	const seconds = Math.max(0, Math.trunc(value));
	if (seconds < 60) return `${seconds}s`;

	const minutes = Math.trunc(seconds / 60);
	if (minutes < 60) return `${minutes}m`;

	const hours = Math.trunc(minutes / 60);
	const remainingMinutes = minutes % 60;
	if (hours >= 24) {
		const days = Math.trunc(hours / 24);
		const remainingHours = hours % 24;
		return `${days}d ${remainingHours}h ${remainingMinutes}m`;
	}

	if (remainingMinutes === 0) return `${hours}h`;
	return `${hours}h ${remainingMinutes}m`;
}

export function formatTokensCompact(value: number): string {
	const abs = Math.abs(value);
	if (abs >= 1_000_000) return `${formatOneDecimal(value / 1_000_000)}M`;
	if (abs >= 1_000) return `${formatOneDecimal(value / 1_000)}K`;
	return `${Math.trunc(value)}`;
}

export function goalStatusLabel(status: GoalStatus): string {
	switch (status) {
		case "active":
			return "active";
		case "paused":
			return "paused";
		case "blocked":
			return "blocked";
		case "budgetLimited":
			return "limited by budget";
		case "complete":
			return "complete";
	}
}

export function goalUsageSummary(goal: Goal): string {
	const parts = [`Objective: ${goal.objective}`];
	if (goal.timeUsedSeconds > 0) parts.push(`Time: ${formatGoalElapsedSeconds(goal.timeUsedSeconds)}.`);
	if (goal.tokenBudget !== undefined) {
		parts.push(`Tokens: ${formatTokensCompact(goal.tokensUsed)}/${formatTokensCompact(goal.tokenBudget)}.`);
	}
	return parts.join(" ");
}

export function formatGoalForTool(goal: Goal | null): string {
	if (!goal) return "No active goal is set.";
	const lines = [
		`Objective: ${goal.objective}`,
		`Status: ${goalStatusLabel(goal.status)}`,
		`Time used: ${formatGoalElapsedSeconds(goal.timeUsedSeconds)}`,
		`Tokens used: ${formatTokensCompact(goal.tokensUsed)}${goal.tokenBudget === undefined ? "" : `/${formatTokensCompact(goal.tokenBudget)}`}`,
	];
	if (goal.completedAt) lines.push(`Completed at: ${new Date(goal.completedAt * 1000).toISOString()}`);
	return lines.join("\n");
}

export function goalToolResponse(goal: Goal | null, includeCompletionBudgetReport: boolean): GoalToolResponse {
	return {
		goal: goal === null ? null : goalToolSnapshot(goal),
		remainingTokens: remainingTokens(goal),
		completionBudgetReport: includeCompletionBudgetReport ? completionBudgetReport(goal) : null,
	};
}

export function formatGoalToolResponse(goal: Goal | null, includeCompletionBudgetReport: boolean): string {
	return JSON.stringify(goalToolResponse(goal, includeCompletionBudgetReport), null, 2);
}

function goalToolSnapshot(goal: Goal): GoalToolSnapshot {
	const snapshot: GoalToolSnapshot = {
		threadId: goal.threadId,
		objective: goal.objective,
		status: goal.status,
		tokensUsed: goal.tokensUsed,
		timeUsedSeconds: goal.timeUsedSeconds,
		createdAt: goal.createdAt,
		updatedAt: goal.updatedAt,
	};
	if (goal.tokenBudget !== undefined) snapshot.tokenBudget = goal.tokenBudget;
	return snapshot;
}

function remainingTokens(goal: Goal | null): number | null {
	if (goal?.tokenBudget === undefined) return null;
	return Math.max(0, goal.tokenBudget - goal.tokensUsed);
}

function completionBudgetReport(goal: Goal | null): string | null {
	if (goal?.status !== "complete") return null;
	if (goal.tokenBudget === undefined && goal.timeUsedSeconds <= 0) return null;
	return "Goal achieved. Report final usage from this tool result's structured goal fields. If `goal.tokenBudget` is present, include token usage from `goal.tokensUsed` and `goal.tokenBudget`. If `goal.timeUsedSeconds` is greater than 0, summarize elapsed time in a concise, human-friendly form appropriate to the response language.";
}

function formatOneDecimal(value: number): string {
	const rounded = value.toFixed(1);
	return rounded.endsWith(".0") ? rounded.slice(0, -2) : rounded;
}

import { randomUUID } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import {
	GoalAlreadyExistsError,
	GoalNotFoundError,
	InvalidGoalStoreError,
	UnsupportedGoalStoreVersionError,
} from "./errors.js";
import type { Goal, GoalAccountingMode, GoalFile, GoalStoreRef, GoalUpdate, TokenUsageSnapshot } from "./types.js";
import { isRecord } from "./types.js";
import { validateObjective, validateTokenBudget } from "./validation.js";

const STORE_VERSION = 1;

export function goalFilePath(ref: GoalStoreRef): string {
	return join(ref.baseDir, `${encodeURIComponent(ref.threadId)}.json`);
}

export async function readGoal(ref: GoalStoreRef): Promise<Goal | null> {
	const filePath = goalFilePath(ref);
	try {
		const raw = await readFile(filePath, "utf8");
		return parseGoalFile(raw).goal;
	} catch (error) {
		if (isMissingFile(error)) return null;
		throw error;
	}
}

export async function writeGoal(ref: GoalStoreRef, goal: Goal | null): Promise<void> {
	const filePath = goalFilePath(ref);
	await mkdir(dirname(filePath), { recursive: true });
	const file: GoalFile = { version: STORE_VERSION, goal };
	await writeFile(filePath, `${JSON.stringify(file, null, 2)}\n`, "utf8");
}

export async function createGoal(ref: GoalStoreRef, objective: string, tokenBudget?: number): Promise<Goal> {
	const current = await readGoal(ref);
	if (current !== null && current.status !== "complete") {
		throw new GoalAlreadyExistsError(
			"cannot create a new goal because this thread has an unfinished goal; complete the existing goal first",
		);
	}

	const normalizedObjective = validateObjective(objective);
	validateTokenBudget(tokenBudget);
	const now = nowSeconds();
	const goal: Goal = {
		id: randomUUID(),
		threadId: ref.threadId,
		objective: normalizedObjective,
		status: "active",
		tokensUsed: 0,
		timeUsedSeconds: 0,
		createdAt: now,
		updatedAt: now,
		lastStartedAt: now,
	};
	if (tokenBudget !== undefined) {
		goal.tokenBudget = tokenBudget;
	}
	await writeGoal(ref, goal);
	return goal;
}

export async function updateGoal(ref: GoalStoreRef, update: GoalUpdate): Promise<Goal> {
	const current = await readGoal(ref);
	if (!current) throw new GoalNotFoundError("cannot update goal: no goal exists");

	const tokenBudget = validateTokenBudget(update.tokenBudget);
	const objective = update.objective === undefined ? current.objective : validateObjective(update.objective);
	const now = nowSeconds();
	const hasObjectiveUpdate = update.objective !== undefined;
	const replacesGoal = hasObjectiveUpdate && (objective !== current.objective || current.status === "complete");
	const requestedStatus = update.status ?? (hasObjectiveUpdate ? "active" : undefined);

	if (replacesGoal) {
		const replacementBudget = tokenBudget === null ? undefined : tokenBudget;
		const status = statusAfterBudgetLimit(requestedStatus ?? "active", 0, replacementBudget);
		const next: Goal = {
			id: randomUUID(),
			threadId: ref.threadId,
			objective,
			status,
			tokensUsed: 0,
			timeUsedSeconds: 0,
			createdAt: now,
			updatedAt: now,
		};
		if (replacementBudget !== undefined) next.tokenBudget = replacementBudget;
		if (status === "active") next.lastStartedAt = now;
		if (status === "complete") next.completedAt = now;
		await writeGoal(ref, next);
		return next;
	}

	const nextTokenBudget = tokenBudget === null ? undefined : (tokenBudget ?? current.tokenBudget);
	const status =
		requestedStatus === undefined
			? statusAfterBudgetUpdate(current.status, current.tokensUsed, nextTokenBudget)
			: statusAfterExplicitStatusUpdate(current.status, requestedStatus, current.tokensUsed, nextTokenBudget);
	const next: Goal = {
		...current,
		objective,
		status,
		updatedAt: now,
	};

	if (tokenBudget === null) {
		delete next.tokenBudget;
	} else if (tokenBudget !== undefined) {
		next.tokenBudget = tokenBudget;
	}

	if (status === "active" && current.status !== "active") {
		next.lastStartedAt = now;
	} else if (status !== "active") {
		delete next.lastStartedAt;
	}

	if (status === "complete") {
		next.completedAt = current.completedAt ?? now;
	} else {
		delete next.completedAt;
	}

	await writeGoal(ref, next);
	return next;
}

export async function clearGoal(ref: GoalStoreRef): Promise<boolean> {
	const hadGoal = (await readGoal(ref)) !== null;
	await writeGoal(ref, null);
	return hadGoal;
}

export async function accountGoalUsage(
	ref: GoalStoreRef,
	usage: TokenUsageSnapshot,
	elapsedSeconds: number,
	mode: GoalAccountingMode = "active",
	expectedGoalId?: string,
): Promise<Goal | null> {
	const goal = await readGoal(ref);
	if (!goal) return goal;
	if (expectedGoalId !== undefined && goal.id !== expectedGoalId) return goal;
	if (!canAccountGoalUsage(goal, mode)) return goal;

	const tokensUsed = goal.tokensUsed + goalTokenDeltaForUsage(usage);
	const now = nowSeconds();
	const next: Goal = {
		...goal,
		tokensUsed,
		timeUsedSeconds: goal.timeUsedSeconds + Math.max(0, Math.trunc(elapsedSeconds)),
		updatedAt: now,
		status: statusAfterAccounting(goal.status, tokensUsed, goal.tokenBudget, mode),
	};
	if (next.status === "budgetLimited") delete next.lastStartedAt;
	await writeGoal(ref, next);
	return next;
}

function canAccountGoalUsage(goal: Goal, mode: GoalAccountingMode): boolean {
	switch (mode) {
		case "activeStatusOnly":
			return goal.status === "active";
		case "active":
			return goal.status === "active" || goal.status === "budgetLimited";
		case "activeOrComplete":
			return goal.status === "active" || goal.status === "budgetLimited" || goal.status === "complete";
		case "activeOrStopped":
			return goal.status === "active" || goal.status === "paused" || goal.status === "budgetLimited";
	}
}

function goalTokenDeltaForUsage(usage: TokenUsageSnapshot): number {
	return Math.max(0, usage.input) + Math.max(0, usage.output);
}

function statusAfterAccounting(
	status: Goal["status"],
	tokensUsed: number,
	tokenBudget: number | undefined,
	mode: GoalAccountingMode,
): Goal["status"] {
	if (tokenBudget === undefined || tokensUsed < tokenBudget) return status;
	switch (mode) {
		case "activeStatusOnly":
		case "active":
		case "activeOrComplete":
			return status === "active" ? "budgetLimited" : status;
		case "activeOrStopped":
			return status === "active" || status === "paused" || status === "budgetLimited" ? "budgetLimited" : status;
	}
}

function statusAfterExplicitStatusUpdate(
	currentStatus: Goal["status"],
	requestedStatus: Goal["status"],
	tokensUsed: number,
	tokenBudget: number | undefined,
): Goal["status"] {
	if (currentStatus === "budgetLimited" && (requestedStatus === "paused" || requestedStatus === "blocked")) {
		return "budgetLimited";
	}
	return statusAfterBudgetLimit(requestedStatus, tokensUsed, tokenBudget);
}

function statusAfterBudgetUpdate(
	currentStatus: Goal["status"],
	tokensUsed: number,
	tokenBudget: number | undefined,
): Goal["status"] {
	if (currentStatus === "active") return statusAfterBudgetLimit(currentStatus, tokensUsed, tokenBudget);
	return currentStatus;
}

function statusAfterBudgetLimit(
	status: Goal["status"],
	tokensUsed: number,
	tokenBudget: number | undefined,
): Goal["status"] {
	return status === "active" && tokenBudget !== undefined && tokensUsed >= tokenBudget ? "budgetLimited" : status;
}

function parseGoalFile(raw: string): GoalFile {
	const parsed: unknown = JSON.parse(raw);
	if (!isRecord(parsed)) throw new InvalidGoalStoreError("goal store must be a JSON object");
	if (parsed["version"] !== STORE_VERSION)
		throw new UnsupportedGoalStoreVersionError("unsupported goal store version");
	const goal = parsed["goal"];
	if (goal !== null && !isGoal(goal)) throw new InvalidGoalStoreError("goal store contains an invalid goal");
	return {
		version: STORE_VERSION,
		goal,
	};
}

function isMissingFile(error: unknown): boolean {
	return isErrorWithCode(error) && error.code === "ENOENT";
}

function isErrorWithCode(error: unknown): error is Error & { code: string } {
	return error instanceof Error && "code" in error && typeof error.code === "string";
}

function isGoal(value: unknown): value is Goal {
	if (!isRecord(value)) return false;
	return (
		typeof value["id"] === "string" &&
		typeof value["threadId"] === "string" &&
		typeof value["objective"] === "string" &&
		isGoalStatus(value["status"]) &&
		(value["tokenBudget"] === undefined || isPositiveSafeInteger(value["tokenBudget"])) &&
		isNonNegativeSafeInteger(value["tokensUsed"]) &&
		isNonNegativeSafeInteger(value["timeUsedSeconds"]) &&
		isNonNegativeSafeInteger(value["createdAt"]) &&
		isNonNegativeSafeInteger(value["updatedAt"]) &&
		(value["lastStartedAt"] === undefined || isNonNegativeSafeInteger(value["lastStartedAt"])) &&
		(value["completedAt"] === undefined || isNonNegativeSafeInteger(value["completedAt"]))
	);
}

function isGoalStatus(value: unknown): value is Goal["status"] {
	return (
		value === "active" ||
		value === "paused" ||
		value === "blocked" ||
		value === "budgetLimited" ||
		value === "complete"
	);
}

function isPositiveSafeInteger(value: unknown): value is number {
	return isSafeInteger(value) && value > 0;
}

function isNonNegativeSafeInteger(value: unknown): value is number {
	return isSafeInteger(value) && value >= 0;
}

function isSafeInteger(value: unknown): value is number {
	return Number.isSafeInteger(value);
}

function nowSeconds(): number {
	return Math.trunc(Date.now() / 1000);
}

export const GOAL_STATUS_VALUES = ["active", "paused", "blocked", "budgetLimited", "complete"] as const;
export const COMPLETABLE_GOAL_STATUS_VALUES = ["complete", "blocked"] as const;

export type GoalStatus = (typeof GOAL_STATUS_VALUES)[number];
export type CompletableGoalStatus = (typeof COMPLETABLE_GOAL_STATUS_VALUES)[number];

export type GoalStoreRef = {
	baseDir: string;
	threadId: string;
};

export type GoalAccountingMode = "activeStatusOnly" | "active" | "activeOrComplete" | "activeOrStopped";

export type Goal = {
	id: string;
	threadId: string;
	objective: string;
	status: GoalStatus;
	tokenBudget?: number;
	tokensUsed: number;
	timeUsedSeconds: number;
	createdAt: number;
	updatedAt: number;
	lastStartedAt?: number;
	completedAt?: number;
};

export type GoalFile = {
	version: 1;
	goal: Goal | null;
};

export type TokenUsageSnapshot = {
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	totalTokens: number;
};

export type GoalUpdate = {
	objective?: string;
	status?: GoalStatus;
	tokenBudget?: number | null;
};

export type GoalToolSnapshot = {
	threadId: string;
	objective: string;
	status: GoalStatus;
	tokenBudget?: number;
	tokensUsed: number;
	timeUsedSeconds: number;
	createdAt: number;
	updatedAt: number;
};

export type GoalToolResponse = {
	goal: GoalToolSnapshot | null;
	remainingTokens: number | null;
	completionBudgetReport: string | null;
};

export function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

import type { ExtensionContext, ReadonlyFooterDataProvider, Theme, ThemeColor } from "@mariozechner/pi-coding-agent";
import type { Component } from "@mariozechner/pi-tui";
import { truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";

import { formatGoalElapsedSeconds, formatTokensCompact } from "./format.js";
import type { Goal, GoalStatus } from "./types.js";
import { isRecord } from "./types.js";

export const STATUS_KEY = "goal";
const LEGACY_WIDGET_KEY = "goal";
let goalFooterInstalled = false;

type GoalFooterIndicator = {
	text: string;
	color: ThemeColor;
};

type FooterTokenStats = {
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	costTotal: number;
};

type FooterAssistantMessage = {
	role: "assistant";
	usage: Record<string, unknown>;
};

export function updateGoalUi(ctx: ExtensionContext, goal: Goal | null): void {
	if (!ctx.hasUI) return;

	ctx.ui.setWidget(LEGACY_WIDGET_KEY, undefined);
	ctx.ui.setStatus(STATUS_KEY, undefined);

	if (!goal) {
		if (goalFooterInstalled) {
			ctx.ui.setFooter(undefined);
			goalFooterInstalled = false;
		}
		return;
	}

	goalFooterInstalled = true;
	ctx.ui.setFooter((_tui, theme, footerData) => new GoalFooterComponent(ctx, footerData, theme, goal));
}

export function goalFooterIndicator(goal: Goal): GoalFooterIndicator {
	const usageText = goalStatusUsage(goal);
	const color = goalStatusColor(goal.status);
	switch (goal.status) {
		case "active":
			return { color, text: usageText === null ? "Pursuing goal" : `Pursuing goal (${usageText})` };
		case "paused":
			return { color, text: "Goal paused (/goal resume)" };
		case "blocked":
			return { color, text: "Goal blocked (/goal resume)" };
		case "budgetLimited":
			return { color, text: usageText === null ? "Goal abandoned" : `Goal unmet (${usageText})` };
		case "complete":
			return { color, text: usageText === null ? "Goal achieved" : `Goal achieved (${usageText})` };
	}
}

export function composeFooterStatusLine(leftText: string, rightText: string, width: number): string {
	if (width <= 0) return "";

	const sanitizedLeftText = sanitizeStatusText(leftText);
	const rightTextWidth = visibleWidth(rightText);
	if (sanitizedLeftText.length === 0) {
		return rightAlignFooterText(rightText, width, rightTextWidth);
	}

	const leftTextWidth = visibleWidth(sanitizedLeftText);
	if (leftTextWidth + 2 + rightTextWidth <= width) {
		return `${sanitizedLeftText}${" ".repeat(width - leftTextWidth - rightTextWidth)}${rightText}`;
	}

	if (rightTextWidth <= width) {
		return rightAlignFooterText(rightText, width, rightTextWidth);
	}

	return truncateToWidth(rightText, width, "");
}

class GoalFooterComponent implements Component {
	private readonly observedAtMilliseconds = Date.now();

	constructor(
		private readonly ctx: ExtensionContext,
		private readonly footerData: ReadonlyFooterDataProvider,
		private readonly theme: Theme,
		private readonly goal: Goal,
	) {}

	render(width: number): string[] {
		const goal = this.renderedGoal();
		return [this.workingDirectoryLine(width), this.statsLine(width), this.goalStatusLine(goal, width)];
	}

	invalidate(): void {}

	private renderedGoal(): Goal {
		if (this.goal.status !== "active" || this.ctx.isIdle()) return this.goal;
		const elapsedSeconds = Math.max(0, Math.round((Date.now() - this.observedAtMilliseconds) / 1000));
		return { ...this.goal, timeUsedSeconds: this.goal.timeUsedSeconds + elapsedSeconds };
	}

	private workingDirectoryLine(width: number): string {
		let workingDirectory = this.ctx.sessionManager.getCwd();
		const homeDirectory = process.env["HOME"] ?? process.env["USERPROFILE"];
		if (homeDirectory !== undefined && workingDirectory.startsWith(homeDirectory)) {
			workingDirectory = `~${workingDirectory.slice(homeDirectory.length)}`;
		}

		const branch = this.footerData.getGitBranch();
		if (branch !== null) {
			workingDirectory = `${workingDirectory} (${branch})`;
		}

		const sessionName = this.ctx.sessionManager.getSessionName();
		if (sessionName !== undefined) {
			workingDirectory = `${workingDirectory} • ${sessionName}`;
		}

		return truncateToWidth(this.theme.fg("dim", workingDirectory), width, this.theme.fg("dim", "..."));
	}

	private statsLine(width: number): string {
		const tokenStats = collectFooterTokenStats(this.ctx);
		const statsParts = footerStatsParts(this.ctx, tokenStats, this.theme);
		let statsLeft = statsParts.join(" ");
		let statsLeftWidth = visibleWidth(statsLeft);
		if (statsLeftWidth > width) {
			statsLeft = truncateToWidth(statsLeft, width, "...");
			statsLeftWidth = visibleWidth(statsLeft);
		}

		const rightSide = footerRightSide(this.ctx, this.footerData);
		const rightSideWidth = visibleWidth(rightSide);
		const minimumPadding = 2;
		const totalNeededWidth = statsLeftWidth + minimumPadding + rightSideWidth;
		const statsLine =
			totalNeededWidth <= width
				? `${statsLeft}${" ".repeat(width - statsLeftWidth - rightSideWidth)}${rightSide}`
				: compactStatsLine(statsLeft, statsLeftWidth, rightSide, width);

		const dimStatsLeft = this.theme.fg("dim", statsLeft);
		const remainder = statsLine.slice(statsLeft.length);
		return `${dimStatsLeft}${this.theme.fg("dim", remainder)}`;
	}

	private goalStatusLine(goal: Goal, width: number): string {
		const indicator = goalFooterIndicator(goal);
		const rightText = this.theme.fg(indicator.color, indicator.text);
		const leftText = Array.from(this.footerData.getExtensionStatuses().entries())
			.filter(([key]) => key !== STATUS_KEY)
			.sort(([leftKey], [rightKey]) => leftKey.localeCompare(rightKey))
			.map(([, text]) => text)
			.join(" ");

		return truncateToWidth(composeFooterStatusLine(leftText, rightText, width), width, this.theme.fg("dim", "..."));
	}
}

function goalStatusUsage(goal: Goal): string | null {
	switch (goal.status) {
		case "active":
			return goal.tokenBudget === undefined
				? formatGoalElapsedSeconds(goal.timeUsedSeconds)
				: `${formatTokensCompact(goal.tokensUsed)} / ${formatTokensCompact(goal.tokenBudget)}`;
		case "paused":
			return null;
		case "blocked":
			return null;
		case "budgetLimited":
			return goal.tokenBudget === undefined
				? null
				: `${formatTokensCompact(goal.tokensUsed)} / ${formatTokensCompact(goal.tokenBudget)} tokens`;
		case "complete":
			return goal.tokenBudget === undefined
				? formatGoalElapsedSeconds(goal.timeUsedSeconds)
				: `${formatTokensCompact(goal.tokensUsed)} tokens`;
	}
}

function goalStatusColor(status: GoalStatus): ThemeColor {
	switch (status) {
		case "active":
			return "accent";
		case "paused":
			return "muted";
		case "blocked":
			return "warning";
		case "budgetLimited":
			return "warning";
		case "complete":
			return "success";
	}
}

function rightAlignFooterText(text: string, width: number, textWidth: number): string {
	if (textWidth >= width) return truncateToWidth(text, width, "");
	return `${" ".repeat(width - textWidth)}${text}`;
}

function sanitizeStatusText(text: string): string {
	return text
		.replace(/[\r\n\t]/g, " ")
		.replace(/ +/g, " ")
		.trim();
}

function collectFooterTokenStats(ctx: ExtensionContext): FooterTokenStats {
	const stats: FooterTokenStats = {
		input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
		costTotal: 0,
	};

	for (const entry of ctx.sessionManager.getEntries()) {
		if (entry.type !== "message" || !isFooterAssistantMessage(entry.message)) continue;
		stats.input += numericUsageField(entry.message.usage, "input");
		stats.output += numericUsageField(entry.message.usage, "output");
		stats.cacheRead += numericUsageField(entry.message.usage, "cacheRead");
		stats.cacheWrite += numericUsageField(entry.message.usage, "cacheWrite");
		stats.costTotal += nestedNumericUsageField(entry.message.usage, "cost", "total");
	}

	return stats;
}

function isFooterAssistantMessage(message: unknown): message is FooterAssistantMessage {
	return isRecord(message) && message["role"] === "assistant" && isRecord(message["usage"]);
}

function footerStatsParts(ctx: ExtensionContext, tokenStats: FooterTokenStats, theme: Theme): string[] {
	const parts: string[] = [];
	if (tokenStats.input !== 0) parts.push(`↑${formatFooterTokens(tokenStats.input)}`);
	if (tokenStats.output !== 0) parts.push(`↓${formatFooterTokens(tokenStats.output)}`);
	if (tokenStats.cacheRead !== 0) parts.push(`R${formatFooterTokens(tokenStats.cacheRead)}`);
	if (tokenStats.cacheWrite !== 0) parts.push(`W${formatFooterTokens(tokenStats.cacheWrite)}`);

	const usingSubscription = ctx.model === undefined ? false : ctx.modelRegistry.isUsingOAuth(ctx.model);
	if (tokenStats.costTotal !== 0 || usingSubscription) {
		parts.push(`$${tokenStats.costTotal.toFixed(3)}${usingSubscription ? " (sub)" : ""}`);
	}

	parts.push(contextUsageText(ctx, theme));
	return parts;
}

function contextUsageText(ctx: ExtensionContext, theme: Theme): string {
	const usage = ctx.getContextUsage();
	const contextWindow = usage?.contextWindow ?? ctx.model?.contextWindow ?? 0;
	const contextPercentValue = usage?.percent ?? 0;
	const autoIndicator = " (auto)";
	const contextPercentDisplay =
		usage?.percent === null || usage?.percent === undefined
			? `?/${formatFooterTokens(contextWindow)}${autoIndicator}`
			: `${usage.percent.toFixed(1)}%/${formatFooterTokens(contextWindow)}${autoIndicator}`;

	if (contextPercentValue > 90) return theme.fg("error", contextPercentDisplay);
	if (contextPercentValue > 70) return theme.fg("warning", contextPercentDisplay);
	return contextPercentDisplay;
}

function footerRightSide(ctx: ExtensionContext, footerData: ReadonlyFooterDataProvider): string {
	const model = ctx.model;
	const modelName = model?.id ?? "no-model";
	const thinkingLevel = currentThinkingLevel(ctx) ?? "off";
	const rightSideWithoutProvider =
		model?.reasoning !== true
			? modelName
			: thinkingLevel === "off"
				? `${modelName} • thinking off`
				: `${modelName} • ${thinkingLevel}`;

	if (model === undefined || footerData.getAvailableProviderCount() <= 1) return rightSideWithoutProvider;

	const rightSideWithProvider = `(${model.provider}) ${rightSideWithoutProvider}`;
	return rightSideWithProvider;
}

function compactStatsLine(statsLeft: string, statsLeftWidth: number, rightSide: string, width: number): string {
	const minimumPadding = 2;
	const availableForRightSide = width - statsLeftWidth - minimumPadding;
	if (availableForRightSide <= 0) return statsLeft;

	const truncatedRightSide = truncateToWidth(rightSide, availableForRightSide, "");
	const padding = " ".repeat(Math.max(0, width - statsLeftWidth - visibleWidth(truncatedRightSide)));
	return `${statsLeft}${padding}${truncatedRightSide}`;
}

function currentThinkingLevel(ctx: ExtensionContext): string | undefined {
	const entries = ctx.sessionManager.getEntries();
	for (let index = entries.length - 1; index >= 0; index -= 1) {
		const entry = entries[index];
		if (entry?.type === "thinking_level_change") return entry.thinkingLevel;
	}
	return undefined;
}

function formatFooterTokens(count: number): string {
	if (count < 1_000) return count.toString();
	if (count < 10_000) return `${(count / 1_000).toFixed(1)}k`;
	if (count < 1_000_000) return `${Math.round(count / 1_000)}k`;
	if (count < 10_000_000) return `${(count / 1_000_000).toFixed(1)}M`;
	return `${Math.round(count / 1_000_000)}M`;
}

function numericUsageField(usage: Record<string, unknown>, key: string): number {
	const value = usage[key];
	return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function nestedNumericUsageField(usage: Record<string, unknown>, outerKey: string, innerKey: string): number {
	const outerValue = usage[outerKey];
	if (!isRecord(outerValue)) return 0;
	return numericUsageField(outerValue, innerKey);
}

export const MAX_OBJECTIVE_LENGTH = 4_000;
const GOAL_TOO_LONG_FILE_HINT =
	"Put longer instructions in a file and refer to that file in the goal, for example: /goal follow the instructions in docs/goal.md.";

export function validateObjective(value: string): string {
	const objective = value.trim();
	if (objective.length === 0) throw new Error("objective must not be empty");
	const objectiveCharacters = [...objective].length;
	if (objectiveCharacters > MAX_OBJECTIVE_LENGTH) {
		throw new Error(
			`Goal objective is too long: ${objectiveCharacters.toLocaleString()} characters. Limit: ${MAX_OBJECTIVE_LENGTH.toLocaleString()} characters. ${GOAL_TOO_LONG_FILE_HINT}`,
		);
	}
	return objective;
}

export function validateTokenBudget(value: number | null | undefined): number | null | undefined {
	if (value === undefined || value === null) return value;
	if (!Number.isSafeInteger(value) || value <= 0) throw new Error("tokenBudget must be a positive safe integer");
	return value;
}

import { createHash } from "node:crypto";
import { homedir } from "node:os";
import { join } from "node:path";

import type { AgentToolResult, ExtensionAPI, ExtensionContext } from "@mariozechner/pi-coding-agent";
import { Type } from "typebox";

import { parseGoalCommand } from "./goal/command.js";
import { shouldQueueGoalContinuationAfterAgentEnd, shouldQueueGoalContinuationWhenIdle } from "./goal/continuation.js";
import { formatGoalForTool, formatGoalToolResponse, goalStatusLabel } from "./goal/format.js";
import { buildBudgetLimitedPrompt, buildContinuationPrompt } from "./goal/prompt.js";
import { GoalAlreadyExistsError } from "./goal/errors.js";
import { accountGoalUsage, clearGoal, createGoal, readGoal, updateGoal } from "./goal/store.js";
import type { Goal, GoalAccountingMode, GoalStoreRef, TokenUsageSnapshot } from "./goal/types.js";
import { COMPLETABLE_GOAL_STATUS_VALUES, isRecord } from "./goal/types.js";
import { updateGoalUi } from "./goal/ui.js";

const GOAL_USAGE = "Usage: /goal <objective>";
const GOAL_EMPTY_HINT = "No goal is currently set.";
const GOAL_CONTINUATION_MESSAGE_TYPE = "pi-goal-continuation";
const GOAL_BUDGET_LIMIT_MESSAGE_TYPE = "pi-goal-budget-limit";
const REPLACE_GOAL_CHOICE = "Replace current goal";
const CANCEL_REPLACE_GOAL_CHOICE = "Cancel";
const RESUME_GOAL_CHOICE = "Resume goal";
const LEAVE_GOAL_PAUSED_CHOICE = "Leave paused";
const EMPTY_USAGE: TokenUsageSnapshot = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0 };
const STALE_EXTENSION_CONTEXT_ERROR_PREFIX = "This extension ctx is stale after session replacement or reload.";

type GoalToolResult = AgentToolResult<Record<string, never>> & { isError?: boolean };
type AssistantUsageMessage = {
	role: "assistant";
	usage: Record<string, unknown>;
};
type AgentGoalAccounting = {
	goalId: string;
	measuredFromMilliseconds: number;
};

export default function (pi: ExtensionAPI): void {
	let agentTurnInProgress = false;
	let agentGoalAccounting: AgentGoalAccounting | null = null;
	let completedThisTurnGoalId: string | null = null;
	let budgetLimitReportedGoalId: string | null = null;

	pi.registerTool({
		name: "create_goal",
		label: "Create Goal",
		description:
			"Create a goal only when explicitly requested by the user or system/developer instructions; do not infer goals from ordinary tasks.\nSet token_budget only when an explicit token budget is requested. Fails if an unfinished goal exists; use update_goal only for status.",
		parameters: Type.Object(
			{
				objective: Type.String({
					description:
						"Required. The concrete objective to start pursuing. This starts a new active goal when no goal exists or replaces the current goal when it is complete.",
				}),
				token_budget: Type.Optional(
					Type.Integer({ description: "Positive token budget for the new goal. Omit unless explicitly requested." }),
				),
			},
			{ additionalProperties: false },
		),
		async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
			const ref = goalStoreRef(ctx);
			let goal: Goal;
			try {
				goal = await createGoal(ref, params.objective, params.token_budget);
			} catch (error) {
				if (error instanceof GoalAlreadyExistsError) return toolText(error.message, true);
				throw error;
			}
			beginAgentGoalAccounting(goal);
			updateGoalUi(ctx, goal);
			return toolText(formatGoalToolResponse(goal, false));
		},
	});

	pi.registerTool({
		name: "update_goal",
		label: "Update Goal",
		description:
			"Update the existing goal.\nUse this tool only to mark the goal achieved or genuinely blocked.\nSet status to `complete` only when the objective has actually been achieved and no required work remains.\nSet status to `blocked` only when the same blocking condition has repeated for at least three consecutive goal turns, counting the original/user-triggered turn and any automatic continuations, and the agent cannot make meaningful progress without user input or an external-state change.\nIf the user resumes a goal that was previously marked `blocked`, treat the resumed run as a fresh blocked audit. If the same blocking condition then repeats for at least three consecutive resumed goal turns, set status to `blocked` again.\nOnce the blocked threshold is satisfied, do not keep reporting that you are still blocked while leaving the goal active; set status to `blocked`.\nDo not use `blocked` merely because the work is hard, slow, uncertain, incomplete, or would benefit from clarification.\nDo not mark a goal complete merely because its budget is nearly exhausted or because you are stopping work.\nYou cannot use this tool to pause, resume, budget-limit, or usage-limit a goal; those status changes are controlled by the user or system.\nWhen marking a budgeted goal achieved with status `complete`, report the final token usage from the tool result to the user.",
		parameters: Type.Object(
			{
				status: Type.Union(
					COMPLETABLE_GOAL_STATUS_VALUES.map((status) => Type.Literal(status)),
					{
						description:
							"Required. Set to `complete` only when the objective is achieved and no required work remains. Set to `blocked` only after the same blocking condition has recurred for at least three consecutive goal turns and the agent is at an impasse. After a previously blocked goal is resumed, the resumed run starts a fresh blocked audit.",
					},
				),
			},
			{ additionalProperties: false },
		),
		async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
			if (params.status !== "complete" && params.status !== "blocked") {
				return toolText(
					"update_goal can only mark the existing goal complete or blocked; pause, resume, budget-limited, and usage-limited status changes are controlled by the user or system",
					true,
				);
			}
			await accountCurrentAgentTurn(ctx, EMPTY_USAGE, "active");
			const goal = await updateGoal(goalStoreRef(ctx), { status: params.status });
			if (params.status === "complete") {
				markGoalCompletedThisTurn(goal);
			} else {
				stopAgentGoalAccounting(goal.id);
			}
			updateGoalUi(ctx, goal);
			return toolText(formatGoalToolResponse(goal, params.status === "complete"));
		},
	});

	pi.registerTool({
		name: "get_goal",
		label: "Get Goal",
		description:
			"Get the current goal for this thread, including status, budgets, token and elapsed-time usage, and remaining token budget.",
		parameters: Type.Object({}, { additionalProperties: false }),
		async execute(_toolCallId, _params, _signal, _onUpdate, ctx) {
			const goal = await readGoal(goalStoreRef(ctx));
			updateGoalUi(ctx, goal);
			return toolText(formatGoalToolResponse(goal, false));
		},
	});

	pi.registerCommand("goal", {
		description: "Set, inspect, pause, resume, or clear the persistent goal",
		handler: async (rawArgs, ctx) => {
			const command = parseGoalCommand(rawArgs);
			try {
				switch (command.kind) {
					case "show": {
						const goal = await readGoal(goalStoreRef(ctx));
						updateGoalUi(ctx, goal);
						ctx.ui.notify(
							goal === null ? `${GOAL_USAGE}\n${GOAL_EMPTY_HINT}` : formatGoalForTool(goal),
							goal ? "info" : "warning",
						);
						return;
					}
					case "setObjective": {
						await setGoalObjective(pi, ctx, command.objective);
						return;
					}
					case "setStatus": {
						if (command.status === "paused") {
							await accountCurrentAgentTurn(ctx, EMPTY_USAGE, "active");
						}
						const goal = await updateGoal(goalStoreRef(ctx), { status: command.status });
						if (goal.status === "active") {
							beginAgentGoalAccounting(goal);
						} else {
							stopAgentGoalAccounting(goal.id);
						}
						updateGoalUi(ctx, goal);
						ctx.ui.notify(`Goal ${goalStatusLabel(goal.status)}\n${formatGoalForTool(goal)}`, "info");
						queueGoalContinuation(pi, ctx, goal);
						return;
					}
					case "clear": {
						await accountCurrentAgentTurn(ctx, EMPTY_USAGE, "active");
						const cleared = await clearGoal(goalStoreRef(ctx));
						clearAgentGoalAccounting();
						updateGoalUi(ctx, null);
						ctx.ui.notify(
							cleared ? "Goal cleared" : "No goal to clear\nThis thread does not currently have a goal.",
							cleared ? "info" : "warning",
						);
						return;
					}
				}
			} catch (error) {
				ctx.ui.notify(errorMessage(error), "error");
			}
		},
	});

	pi.on("session_start", async (event, ctx) => {
		const goal = await readGoal(goalStoreRef(ctx));
		if (goal?.status === "active") {
			beginAgentGoalAccounting(goal);
		} else {
			clearAgentGoalAccounting();
		}
		updateGoalUi(ctx, goal);
		if (await maybePromptResumePausedGoal(pi, ctx, event.reason, goal)) {
			return;
		}
		if (shouldQueueGoalContinuationWhenIdle(goal, ctx.isIdle(), ctx.hasPendingMessages())) {
			queueHiddenGoalPrompt(pi, GOAL_CONTINUATION_MESSAGE_TYPE, buildContinuationPrompt(goal));
		}
	});

	pi.on("agent_start", async (_event, ctx) => {
		agentTurnInProgress = true;
		completedThisTurnGoalId = null;
		const goal = await readGoal(goalStoreRef(ctx));
		if (goal?.status === "active") {
			beginAgentGoalAccounting(goal);
		} else {
			agentGoalAccounting = null;
		}
	});

	pi.on("agent_end", async (event, ctx) => {
		const mode: GoalAccountingMode = completedThisTurnGoalId === null ? "active" : "activeOrComplete";
		const goal = await accountCurrentAgentTurn(ctx, collectAssistantUsage(event.messages), mode);
		agentTurnInProgress = false;
		completedThisTurnGoalId = null;
		if (goal?.status === "active") {
			beginAgentGoalAccounting(goal);
		} else {
			clearAgentGoalAccounting();
		}
		updateGoalUiBestEffort(ctx, goal);
		if (goal?.status === "budgetLimited") {
			if (!ctx.hasPendingMessages() && budgetLimitReportedGoalId !== goal.id) {
				budgetLimitReportedGoalId = goal.id;
				queueHiddenGoalPrompt(pi, GOAL_BUDGET_LIMIT_MESSAGE_TYPE, buildBudgetLimitedPrompt(goal));
			}
			return;
		}
		if (
			goal?.status === "active" &&
			shouldQueueGoalContinuationAfterAgentEnd(goal, ctx.hasPendingMessages(), event.messages)
		) {
			queueHiddenGoalPrompt(pi, GOAL_CONTINUATION_MESSAGE_TYPE, buildContinuationPrompt(goal));
		}
	});

	pi.on("session_shutdown", async (_event, ctx) => {
		if (agentGoalAccounting !== null) {
			await accountCurrentAgentTurn(ctx, EMPTY_USAGE, "active");
		}
		clearAgentGoalAccounting();
	});

	async function setGoalObjective(pi: ExtensionAPI, ctx: ExtensionContext, objective: string): Promise<void> {
		const ref = goalStoreRef(ctx);
		const current = await readGoal(ref);
		if (current !== null) {
			const shouldReplace = await confirmReplaceGoal(ctx, objective);
			if (!shouldReplace) return;
		}

		if (current?.status === "active") {
			await accountCurrentAgentTurn(ctx, EMPTY_USAGE, "active");
		}
		const goal = current === null ? await createGoal(ref, objective) : await updateGoal(ref, { objective });
		if (goal.status === "active") beginAgentGoalAccounting(goal);
		updateGoalUi(ctx, goal);
		ctx.ui.notify(`Goal ${goalStatusLabel(goal.status)}\n${formatGoalForTool(goal)}`, "info");
		queueGoalContinuation(pi, ctx, goal);
	}

	async function confirmReplaceGoal(ctx: ExtensionContext, objective: string): Promise<boolean> {
		if (!ctx.hasUI) return true;
		const choice = await ctx.ui.select(`Replace goal?\nNew objective: ${objective}`, [
			REPLACE_GOAL_CHOICE,
			CANCEL_REPLACE_GOAL_CHOICE,
		]);
		return choice === REPLACE_GOAL_CHOICE;
	}

	async function maybePromptResumePausedGoal(
		pi: ExtensionAPI,
		ctx: ExtensionContext,
		sessionStartReason: string,
		goal: Goal | null,
	): Promise<boolean> {
		if (!isResumeOfPausedGoal(ctx, sessionStartReason, goal)) {
			return false;
		}

		const choice = await ctx.ui.select(`Resume paused goal?\nGoal: ${goal.objective}`, [
			RESUME_GOAL_CHOICE,
			LEAVE_GOAL_PAUSED_CHOICE,
		]);
		if (choice !== RESUME_GOAL_CHOICE) return true;

		const resumed = await updateGoal(goalStoreRef(ctx), { status: "active" });
		beginAgentGoalAccounting(resumed);
		updateGoalUi(ctx, resumed);
		ctx.ui.notify(`Goal ${goalStatusLabel(resumed.status)}\n${formatGoalForTool(resumed)}`, "info");
		queueGoalContinuation(pi, ctx, resumed);
		return true;
	}

	function beginAgentGoalAccounting(goal: Goal): void {
		if (goal.status !== "active") return;
		if (agentGoalAccounting?.goalId === goal.id) return;
		agentGoalAccounting = { goalId: goal.id, measuredFromMilliseconds: Date.now() };
	}

	function markGoalCompletedThisTurn(goal: Goal): void {
		if (!agentTurnInProgress) return;
		completedThisTurnGoalId = goal.id;
		agentGoalAccounting = { goalId: goal.id, measuredFromMilliseconds: Date.now() };
	}

	function stopAgentGoalAccounting(goalId: string): void {
		if (agentGoalAccounting?.goalId === goalId) {
			agentGoalAccounting = null;
		}
		if (completedThisTurnGoalId === goalId) {
			completedThisTurnGoalId = null;
		}
	}

	function clearAgentGoalAccounting(): void {
		agentGoalAccounting = null;
		completedThisTurnGoalId = null;
	}

	async function accountCurrentAgentTurn(
		ctx: ExtensionContext,
		usage: TokenUsageSnapshot,
		mode: GoalAccountingMode,
	): Promise<Goal | null> {
		const accounting = agentGoalAccounting;
		const ref = goalStoreRef(ctx);
		if (accounting === null) return readGoal(ref);

		const now = Date.now();
		const elapsedSeconds = Math.max(0, Math.round((now - accounting.measuredFromMilliseconds) / 1000));
		const goal = await accountGoalUsage(ref, usage, elapsedSeconds, mode, accounting.goalId);
		if (goal?.id === accounting.goalId) {
			agentGoalAccounting = { goalId: accounting.goalId, measuredFromMilliseconds: now };
		} else {
			clearAgentGoalAccounting();
		}
		return goal;
	}
}

function updateGoalUiBestEffort(ctx: ExtensionContext, goal: Goal | null): void {
	try {
		updateGoalUi(ctx, goal);
	} catch (error) {
		if (error instanceof Error && error.message.startsWith(STALE_EXTENSION_CONTEXT_ERROR_PREFIX)) {
			return;
		}
		throw error;
	}
}

function isResumeOfPausedGoal(ctx: ExtensionContext, sessionStartReason: string, goal: Goal | null): goal is Goal {
	return (
		sessionStartReason === "resume" &&
		goal?.status === "paused" &&
		ctx.hasUI &&
		ctx.isIdle() &&
		!ctx.hasPendingMessages()
	);
}

function queueGoalContinuation(pi: ExtensionAPI, ctx: ExtensionContext, goal: Goal): void {
	if (shouldQueueGoalContinuationWhenIdle(goal, ctx.isIdle(), ctx.hasPendingMessages())) {
		queueHiddenGoalPrompt(pi, GOAL_CONTINUATION_MESSAGE_TYPE, buildContinuationPrompt(goal));
	}
}

function queueHiddenGoalPrompt(pi: ExtensionAPI, customType: string, content: string): void {
	pi.sendMessage({ customType, content, display: false }, { triggerTurn: true, deliverAs: "followUp" });
}

function goalStoreRef(ctx: ExtensionContext): GoalStoreRef {
	const sessionFile = ctx.sessionManager.getSessionFile();
	const baseDir =
		sessionFile === undefined
			? join(agentDir(), "extensions", "pi-goal", "no-session", cwdStoreKey(ctx.cwd))
			: join(ctx.sessionManager.getSessionDir(), "extensions", "pi-goal");

	return {
		baseDir,
		threadId: ctx.sessionManager.getSessionId(),
	};
}

function agentDir(): string {
	return process.env["PI_CODING_AGENT_DIR"] ?? join(homedir(), ".pi", "agent");
}

function cwdStoreKey(cwd: string): string {
	return createHash("sha256").update(cwd).digest("hex").slice(0, 24);
}

function toolText(text: string, isError = false): GoalToolResult {
	return { content: [{ type: "text" as const, text }], details: {}, isError };
}

function collectAssistantUsage(messages: unknown[]): TokenUsageSnapshot {
	const usage: TokenUsageSnapshot = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0 };
	for (const message of messages) {
		if (!isAssistantUsageMessage(message)) continue;
		usage.input += numericUsageField(message.usage, "input");
		usage.output += numericUsageField(message.usage, "output");
		usage.cacheRead += numericUsageField(message.usage, "cacheRead");
		usage.cacheWrite += numericUsageField(message.usage, "cacheWrite");
		usage.totalTokens += numericUsageField(message.usage, "totalTokens");
	}
	return usage;
}

function isAssistantUsageMessage(message: unknown): message is AssistantUsageMessage {
	if (!isRecord(message)) return false;
	return message["role"] === "assistant" && isRecord(message["usage"]);
}

function numericUsageField(usage: Record<string, unknown>, key: string): number {
	const value = usage[key];
	return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "bun:test";

import { accountGoalUsage, createGoal, readGoal, updateGoal } from "../src/goal/store.js";
import type { TokenUsageSnapshot } from "../src/goal/types.js";
import type { GoalStoreRef } from "../src/goal/types.js";
import { GOAL_STATUS_VALUES } from "../src/goal/types.js";

const tempDirs: string[] = [];

async function tempStore(threadId: string): Promise<GoalStoreRef> {
	const dir = await mkdtemp(join(tmpdir(), "pi-goal-codex-"));
	tempDirs.push(dir);
	return { baseDir: dir, threadId };
}

describe("codex alignment: blocked status", () => {
	afterEach(async () => {
		await Promise.all(tempDirs.splice(0).map((dir) => rm(dir, { recursive: true, force: true })));
	});

	it("includes blocked in the goal status vocabulary", () => {
		expect(GOAL_STATUS_VALUES).toContain("blocked");
	});

	it("marks an active goal blocked and clears its lastStartedAt", async () => {
		const ref = await tempStore("thread-block");
		await createGoal(ref, "Pursue the objective");

		const blocked = await updateGoal(ref, { status: "blocked" });

		expect(blocked.status).toBe("blocked");
		expect(blocked.lastStartedAt).toBeUndefined();
		expect((await readGoal(ref))?.status).toBe("blocked");
	});

	it("preserves budgetLimited when a blocked update is requested", async () => {
		const ref = await tempStore("thread-block-budget");
		await createGoal(ref, "Budget goal", 10);
		const overBudget: TokenUsageSnapshot = { input: 20, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 20 };
		const limited = await accountGoalUsage(ref, overBudget, 0, "active");
		expect(limited?.status).toBe("budgetLimited");

		const afterBlock = await updateGoal(ref, { status: "blocked" });

		expect(afterBlock.status).toBe("budgetLimited");
	});
});

describe("codex alignment: create replaces only a complete goal", () => {
	afterEach(async () => {
		await Promise.all(tempDirs.splice(0).map((dir) => rm(dir, { recursive: true, force: true })));
	});

	it("replaces a completed goal with a fresh active goal", async () => {
		const ref = await tempStore("thread-replace-complete");
		const first = await createGoal(ref, "First objective");
		await updateGoal(ref, { status: "complete" });

		const replacement = await createGoal(ref, "Second objective");

		expect(replacement.status).toBe("active");
		expect(replacement.objective).toBe("Second objective");
		expect(replacement.id).not.toBe(first.id);
		expect(replacement.tokensUsed).toBe(0);
	});

	it("rejects creating a goal while an unfinished goal exists with the codex message", async () => {
		const ref = await tempStore("thread-unfinished");
		await createGoal(ref, "Active objective");

		await expect(createGoal(ref, "Another objective")).rejects.toThrow(
			"cannot create a new goal because this thread has an unfinished goal; complete the existing goal first",
		);
	});

	it("rejects creating a goal while a blocked goal exists", async () => {
		const ref = await tempStore("thread-blocked-exists");
		await createGoal(ref, "Blocked objective");
		await updateGoal(ref, { status: "blocked" });

		await expect(createGoal(ref, "New objective")).rejects.toThrow("has an unfinished goal");
	});
});

import { describe, expect, it } from "bun:test";

import { parseGoalCommand } from "../src/goal/command.js";

describe("goal command parsing", () => {
	it("treats bare /goal as a summary request", () => {
		expect(parseGoalCommand("")).toEqual({ kind: "show" });
	});

	it("treats arbitrary text after /goal as the objective", () => {
		expect(parseGoalCommand("ship the Codex style flow --token-budget 88")).toEqual({
			kind: "setObjective",
			objective: "ship the Codex style flow --token-budget 88",
		});
	});

	it("does not require or special-case a set subcommand", () => {
		expect(parseGoalCommand("set up the release")).toEqual({
			kind: "setObjective",
			objective: "set up the release",
		});
	});

	it("keeps Codex-style control commands reserved", () => {
		expect(parseGoalCommand("pause")).toEqual({ kind: "setStatus", status: "paused" });
		expect(parseGoalCommand("resume")).toEqual({ kind: "setStatus", status: "active" });
		expect(parseGoalCommand("clear")).toEqual({ kind: "clear" });
	});

	it("treats non-Codex control words as objectives", () => {
		expect(parseGoalCommand("status")).toEqual({ kind: "setObjective", objective: "status" });
		expect(parseGoalCommand("complete")).toEqual({ kind: "setObjective", objective: "complete" });
		expect(parseGoalCommand("help")).toEqual({ kind: "setObjective", objective: "help" });
	});
});

import { describe, expect, it } from "bun:test";

import {
	shouldQueueGoalContinuationAfterAgentEnd,
	shouldQueueGoalContinuationWhenIdle,
} from "../src/goal/continuation.js";
import type { Goal } from "../src/goal/types.js";

const cleanTurn = [{ role: "assistant", stopReason: "stop", content: [{ type: "text", text: "done" }] }];

describe("goal continuation policy", () => {
	it("continues an active goal after a clean agent turn when no user work is pending", () => {
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "active" }), false, cleanTurn)).toBe(true);
	});

	it("does not continue after an agent turn when another message is already pending", () => {
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "active" }), true, cleanTurn)).toBe(false);
	});

	it("only auto-continues active goals after an agent turn", () => {
		expect(shouldQueueGoalContinuationAfterAgentEnd(null, false, cleanTurn)).toBe(false);
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "paused" }), false, cleanTurn)).toBe(false);
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "budgetLimited" }), false, cleanTurn)).toBe(
			false,
		);
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "complete" }), false, cleanTurn)).toBe(false);
	});

	it("does not continue after a turn that ended with a provider error", () => {
		const erroredTurn = [
			{ role: "assistant", stopReason: "error", errorMessage: "boom", content: [] },
		];
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "active" }), false, erroredTurn)).toBe(false);
	});

	it("does not continue after a turn whose last tool result was aborted", () => {
		const abortedTurn = [
			{ role: "assistant", stopReason: "toolUse", content: [{ type: "toolCall", id: "1", name: "bash" }] },
			{ role: "toolResult", isError: true, content: [{ type: "text", text: "Aborted by user" }] },
		];
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "active" }), false, abortedTurn)).toBe(false);
	});

	it("continues after a turn whose tool failed for a non-abort reason", () => {
		const toolFailureTurn = [
			{ role: "assistant", stopReason: "toolUse", content: [{ type: "toolCall", id: "1", name: "bash" }] },
			{ role: "toolResult", isError: true, content: [{ type: "text", text: "command not found" }] },
			{ role: "assistant", stopReason: "stop", content: [{ type: "text", text: "recovered" }] },
		];
		expect(shouldQueueGoalContinuationAfterAgentEnd(testGoal({ status: "active" }), false, toolFailureTurn)).toBe(
			true,
		);
	});

	it("requires idle state for command and session-start continuation", () => {
		expect(shouldQueueGoalContinuationWhenIdle(testGoal({ status: "active" }), true, false)).toBe(true);
		expect(shouldQueueGoalContinuationWhenIdle(testGoal({ status: "active" }), false, false)).toBe(false);
		expect(shouldQueueGoalContinuationWhenIdle(testGoal({ status: "active" }), true, true)).toBe(false);
	});
});

function testGoal(overrides: Partial<Goal> = {}): Goal {
	return {
		id: "goal-1",
		threadId: "thread-1",
		objective: "Keep going until complete",
		status: "active",
		tokensUsed: 0,
		timeUsedSeconds: 0,
		createdAt: 1_777_766_400,
		updatedAt: 1_777_766_400,
		...overrides,
	};
}

